import type { PhoneCallOutcome } from "../domain/models/phone";

export type PilotSeedCandidate = {
  candidate_id: string;
  student_name: string;
  class_group: string;
  general_status_label: string;
  general_status_key_suggestion: string;
  source_campaign: string;
  district: string;
  school: string;
  priority: string;
  visibility_expected: string;
  candidate_note: string;
};

export type PilotSeedGuardian = {
  guardian_id: string;
  candidate_id: string;
  student_name: string;
  relation: string;
  guardian_name: string;
  guardian_note: string;
  badge_expected: string;
};

export type PilotSeedPhone = {
  phone_id: string;
  candidate_id: string;
  student_name: string;
  phone_slot: number;
  phone_label: string;
  guardian_id: string | null;
  guardian_relation: string | null;
  badge_expected: string | null;
  phone_number: string;
  phone_outcome_label: string;
  phone_outcome_key: PhoneCallOutcome;
  is_primary: string;
  phone_note: string;
};

export type PilotSeedCallLog = {
  call_log_id: string;
  candidate_id: string;
  student_name: string;
  phone_id: string;
  call_time: string;
  call_result_label: string;
  call_result_key_suggestion: string;
  call_note: string;
};

export type PilotSeedReminder = {
  reminder_id: string;
  candidate_id: string;
  student_name: string;
  phone_id: string;
  reminder_at: string;
  reminder_status_label: string;
  reminder_status_key_suggestion: string;
  visibility_expected: string;
  reminder_note: string;
};

export type PilotSeedAppointment = {
  appointment_id: string;
  candidate_id: string;
  student_name: string;
  guardian_id: string;
  appointment_at: string;
  appointment_status_label: string;
  appointment_status_key_suggestion: string;
  appointment_note: string;
};

